using He_Thong_GYM.BLL;using He_Thong_GYM.Models;
namespace He_Thong_GYM.Forms;
public partial class FrmTaiKhoan:Form
{
 private readonly DangNhapBLL _bll=new();private readonly NhanVienBLL _nhanVienBLL=new();private TaiKhoan? _chon;
 public FrmTaiKhoan(){InitializeComponent();}
 private async void FrmTaiKhoan_Load(object? s,EventArgs e){try{cboNhanVien.DataSource=await _nhanVienBLL.LayNhanVienDangLamAsync();cboNhanVien.DisplayMember=nameof(NhanVien.HoTen);cboNhanVien.ValueMember=nameof(NhanVien.MaNV);cboVaiTro.DataSource=await _bll.LayVaiTroAsync();await TaiAsync();}catch(Exception ex){MessageBox.Show(ex.Message,"Lỗi dữ liệu",MessageBoxButtons.OK,MessageBoxIcon.Error);}}
 private async Task TaiAsync(){dgvTaiKhoan.DataSource=await _bll.LayDanhSachTaiKhoanAsync();}
 private void dgvTaiKhoan_SelectionChanged(object? s,EventArgs e){if(dgvTaiKhoan.CurrentRow?.DataBoundItem is not TaiKhoan t)return;_chon=t;txtTenDangNhap.Text=t.TenDangNhap;cboNhanVien.SelectedValue=t.MaNV;cboVaiTro.SelectedItem=t.VaiTro;lblTrangThai.Text=$"Tài khoản đang chọn: {t.TenDangNhap} - {t.TrangThai}";}
 private void btnTaoMoi_Click(object? s,EventArgs e){_chon=null;txtTenDangNhap.Clear();txtMatKhau.Clear();if(cboNhanVien.Items.Count>0)cboNhanVien.SelectedIndex=0;if(cboVaiTro.Items.Count>0)cboVaiTro.SelectedIndex=0;lblTrangThai.Text="Nhập thông tin để tạo tài khoản mới.";}
 private async void btnLuu_Click(object? s,EventArgs e){try{if(_chon is not null)throw new InvalidOperationException("Chỉ tạo mới tài khoản tại màn hình này. Dùng nút đặt lại mật khẩu hoặc khóa/mở khóa cho tài khoản đã có.");await _bll.TaoTaiKhoanAsync(new TaiKhoan{TenDangNhap=txtTenDangNhap.Text.Trim(),MaNV=cboNhanVien.SelectedValue is int maNV?maNV:0,VaiTro=cboVaiTro.Text},txtMatKhau.Text);await TaiAsync();MessageBox.Show("Đã tạo tài khoản với mật khẩu hash.","Thành công",MessageBoxButtons.OK,MessageBoxIcon.Information);}catch(Exception ex){MessageBox.Show(ex.Message,"Không thể lưu",MessageBoxButtons.OK,MessageBoxIcon.Warning);}}
 private async void btnKhoaMo_Click(object? s,EventArgs e){if(_chon is null)return;var next=_chon.TrangThai=="Hoạt động"?"Khóa":"Hoạt động";try{await _bll.CapNhatTrangThaiTaiKhoanAsync(_chon.MaTK,next);await TaiAsync();}catch(Exception ex){MessageBox.Show(ex.Message,"Lỗi",MessageBoxButtons.OK,MessageBoxIcon.Error);}}
 private async void btnDatLaiMatKhau_Click(object? s,EventArgs e){if(_chon is null){MessageBox.Show("Hãy chọn tài khoản.");return;}if(txtMatKhau.Text.Length<8){MessageBox.Show("Nhập mật khẩu mới tối thiểu 8 ký tự vào ô Mật khẩu.");return;}try{var n=new NguoiDung{MaTK=_chon.MaTK};await _bll.DoiMatKhauAsync(n,txtMatKhau.Text);txtMatKhau.Clear();MessageBox.Show("Đã đặt lại mật khẩu.","Thành công",MessageBoxButtons.OK,MessageBoxIcon.Information);}catch(Exception ex){MessageBox.Show(ex.Message,"Lỗi",MessageBoxButtons.OK,MessageBoxIcon.Warning);}}
}
